sys_script_include.script:
var CIAudCMDBWriter = Class.create();
CIAudCMDBWriter.prototype = {

    initialize: function() {
        this.TABLE_CANDIDATE = 'x_1412526_ai_ci_re_relationship_candidate';
        this.TABLE_AUDIT     = 'x_1412526_ai_ci_re_ci_audit_log';
    },

    writeRelationship: function(candidateSysId) {
        var cand = new GlideRecord(this.TABLE_CANDIDATE);
        if (!cand.get(candidateSysId)) {
            gs.error('CIAudCMDBWriter: Candidate not found: ' + candidateSysId);
            return null;
        }

        var validator = new CIAudIREValidator();
        if (validator._isDuplicate(
                cand.source_ci.toString(),
                cand.target_ci.toString(),
                cand.relationship_type.toString())) {
            cand.status = 'Duplicate';
            cand.update();
            this._audit('Write', candidateSysId, 'Skipped', 'Relationship already exists in CMDB at write time');
            return null;
        }

        var rel = new GlideRecord('cmdb_rel_ci');
        rel.parent = cand.source_ci;
        rel.child  = cand.target_ci;
        rel.type   = cand.relationship_type;
        var newRelId = rel.insert();

        if (!newRelId) {
            this._audit('Write', candidateSysId, 'Failed', 'cmdb_rel_ci insert returned no sys_id');
            gs.error('CIAudCMDBWriter: Insert failed for candidate ' + candidateSysId);
            return null;
        }

        cand.status          = 'Written';
        cand.cmdb_rel_sys_id = newRelId;
        cand.update();

        this._audit('Write', candidateSysId, 'Success',
            'Relationship written to CMDB: ' + newRelId);

        gs.info('CIAudCMDBWriter: Written relationship ' + newRelId +
            ' for candidate ' + candidateSysId);
        return newRelId;
    },

    stageCandidate: function(candidate, ireResult, logStagingSysId) {
        var highThreshold = parseFloat(gs.getProperty('x_1412526_ai_ci_re.confidence.high', '0.85'));
        var lowThreshold  = parseFloat(gs.getProperty('x_1412526_ai_ci_re.confidence.low',  '0.60'));
        var score         = parseFloat(candidate.confidence);

        var tier = score >= highThreshold ? 'High' :
                   score >= lowThreshold  ? 'Medium' : 'Low';

        var cand = new GlideRecord(this.TABLE_CANDIDATE);
        cand.source_ci         = ireResult.sourceSysId;
        cand.target_ci         = ireResult.targetSysId;
        cand.relationship_type = ireResult.relTypeSysId;
        cand.confidence_score  = score;
        cand.confidence_tier   = tier;
        cand.evidence_text     = candidate.evidence || '';
        cand.llm_rationale     = candidate.relationship_type + ' inferred from discovery log';
        cand.status            = 'Pending';
        cand.log_source        = logStagingSysId;
        var candSysId = cand.insert();

        this._audit('Parse', candSysId, 'Success',
            'Candidate staged: ' + candidate.source_ci_name +
            ' -> ' + candidate.target_ci_name +
            ' (' + tier + ', ' + score + ')');

        if (tier === 'High') {
            return this.writeRelationship(candSysId);
        }

        return candSysId;
    },

    _audit: function(operation, candidateSysId, result, detail) {
        var log = new GlideRecord(this.TABLE_AUDIT);
        log.operation   = operation;
        log.candidate   = candidateSysId;
        log.result      = result;
        log.detail      = detail;
        log.executed_by = gs.getUserID();
        log.insert();
    },

    type: 'CIAudCMDBWriter'
};
